def DR(ar, en, tr):
    """a reading or an iʿrāb that is al-Durra's"""
    return (" — " + ar + " (الدُّرَّةُ)", " — " + en + " (al-Durra)", " — " + tr + " (Dürre)")
def IDHA(full="إِذَا", c=None, n=NO, g=()):
    a = "ظَرْفٌ لِمَا يُسْتَقْبَلُ مِنَ الزَّمَانِ، خَافِضٌ لِشَرْطِهِ مَنْصُوبٌ بِجَوَابِهِ، مَبْنِيٌّ عَلَى السُّكُونِ فِي مَحَلِّ نَصْبٍ"
    e = "an adverb of time to come, annexed to its condition and governed by its answer; built on sukun, in the seat of nasb"
    t = "gelecek zaman zarfı; şartına muzâf, cevabıyla mansûb; sükûn üzere mebnî, mahallen mansûb"
    ar0 = en0 = tr0 = ""; segs = None
    if c:
        k, ar0, en0, tr0 = CONJ[c]; segs = SG((full[:2], k, "conj"), (full[2:], "idha", "noun"))
    return T(full, "idha", "noun", ["idha-shartiyya", "maful-fih"] + list(g), ar0 + a + n[0] + ".", cap(en0 + e + n[1] + "."), cap(tr0 + t + n[2] + "."), segs=segs)
def HATTA(n=NO):
    return T("حَتَّى", "hatta", "part", ["ila-hatta-fi-wal-ba-fil-kafiya"], "حَرْفُ ابْتِدَاءٍ: يَبْتَدِئُ بَعْدَهُ الْكَلَامُ وَلَا يَعْمَلُ فِيهِ (الدُّرَّةُ)" + n[0] + ".",
             "Ḥattā that opens a new clause (ibtidāʾiyya): it governs nothing after it (al-Durra)" + n[1] + ".", "İbtidâ hattâsı: ardından yeni söz başlar, ona amel etmez (Dürre)" + n[2] + ".")
AW = lambda: T("أَوْ", "aw", "part", ["atf-nasaq"], "حَرْفُ عَطْفٍ.", "A conjunction: «or».", "Atıf harfi: «yahut».")
QAD = lambda: T("قَدْ", "qad", "part", ["qad-harf"], "حَرْفُ تَحْقِيقٍ يُقَرِّبُ الْمَاضِيَ مِنَ الْحَالِ.", "A particle of realisation: it brings the past near to the present.", "Tahkîk harfi; mâzîyi hâle yaklaştırır.")
NAQA = DZ("هِيَ يَعُودُ عَلَى النَّاقَةِ", "«she» — the she-camel", "dişi deveye dönen gizli «o»")
