VK["mtk"] = ("فِعْلٌ مَاضٍ نَاقِصٌ مَبْنِيٌّ عَلَى الْفَتْحِ، وَالتَّاءُ لِلتَّأْنِيثِ", "a defective past verb built on fatha (the ta marks the feminine)", "fetha üzere mebnî nâkıs mâzî (tâ te'nîs içindir)")
VK["mk"] = ("فِعْلٌ مَاضٍ نَاقِصٌ مَبْنِيٌّ عَلَى الْفَتْحِ", "a defective past verb built on fatha", "fetha üzere mebnî nâkıs mâzî")
